1	// Semantic cache and RAG context layer for the web-chat handler.
2	//
3	// Flow:
4	//  1. Embed the incoming question (OpenAI text-embedding-3-small).
5	//  2. If a past Q&A has cosine similarity >= cacheHitThreshold AND positive
6	//     user feedback → return the cached answer immediately (no LLM call).
7	//  3. Otherwise inject the top-k most similar past Q&A pairs plus any curated
8	//     location knowledge into the system prompt as RAG context.
9	//  4. After the LLM responds, store the new Q&A + embedding asynchronously.
10	//  5. When the user gives thumbs-up, increment feedback_score; if coordinates
11	//     are detected in the answer, also populate location_knowledge.
12	
13	package main
14	
15	import (
16		"context"
17		"encoding/json"
18		"fmt"
19		"log"
20		"math"
21		"regexp"
22		"strconv"
23		"strings"
24		"time"
25	)
26	
27	const (
28		// cacheHitThreshold: similarity above this + positive feedback → skip LLM.
29		// Lower than neural-embedding threshold because feature-hash cosine scores
30		// are sparser; 0.85 corresponds roughly to very similar phrasing.
31		cacheHitThreshold = float32(0.85)
32		// ragContextThreshold: similarity above this → include in RAG context.
33		ragContextThreshold = float32(0.50)
34		// ragTopK: maximum number of similar Q&A pairs to inject.
35		ragTopK = 3
36	)
37	
38	// qaEntry is a row from qa_embeddings.
39	type qaEntry struct {
40		ID            int64
41		Question      string
42		Answer        string
43		Embedding     []float32
44		FeedbackScore int
45	}
46	
47	// checkSemanticCache looks for a positively-rated cached answer with high
48	// cosine similarity to the given embedding. Returns ("", 0) on miss.
49	func checkSemanticCache(embedding []float32) (answer string, chatID int64) {
50		if !duckDBAvailable() || len(embedding) == 0 {
51			return "", 0
52		}
53		entries, err := loadQAEmbeddings(true)
54		if err != nil {
55			log.Printf("semantic cache load: %v", err)
56			return "", 0
57		}
58		var bestScore float32
59		var best *qaEntry
60		for i := range entries {
61			if s := cosineSimilarity(embedding, entries[i].Embedding); s > bestScore {
62				bestScore = s
63				best = &entries[i]
64			}
65		}
66		if bestScore >= cacheHitThreshold && best != nil {
67			return best.Answer, best.ID
68		}
69		return "", 0
70	}
71	
72	// buildRAGContext returns a formatted string of the top-k most similar past
73	// Q&A pairs (similarity >= ragContextThreshold) to prepend to the system prompt.
74	func buildRAGContext(embedding []float32) string {
75		if !duckDBAvailable() || len(embedding) == 0 {
76			return ""
77		}
78		entries, err := loadQAEmbeddings(false)
79		if err != nil {
80			log.Printf("RAG context load: %v", err)
81			return ""
82		}
83	
84		type scored struct {
85			e     *qaEntry
86			score float32
87		}
88		var candidates []scored
89		for i := range entries {
90			if s := cosineSimilarity(embedding, entries[i].Embedding); s >= ragContextThreshold {
91				candidates = append(candidates, scored{&entries[i], s})
92			}
93		}
94		if len(candidates) == 0 {
95			return ""
96		}
97	
98		// Partial sort: bring top-k to the front.
99		limit := ragTopK
100		if len(candidates) < limit {
101			limit = len(candidates)
102		}
103		for i := 0; i < limit; i++ {
104			for j := i + 1; j < len(candidates); j++ {
105				if candidates[j].score > candidates[i].score {
106					candidates[i], candidates[j] = candidates[j], candidates[i]
107				}
108			}
109		}
110	
111		var sb strings.Builder
112		sb.WriteString("RELEVANT PAST Q&A (use as context, do not quote verbatim):\n")
113		for _, c := range candidates[:limit] {
114			ans := c.e.Answer
115			if len(ans) > 500 {
116				ans = ans[:500] + "…"
117			}
118			sb.WriteString(fmt.Sprintf("Q: %s\nA: %s\n\n", c.e.Question, ans))
119		}
120		return sb.String()
121	}
122	
123	// getLocationKnowledge returns curated geographic notes from location_knowledge.
124	// Currently returns all notes (capped at 20); future: filter by detected coordinates.
125	func getLocationKnowledge() string {
126		if !duckDBAvailable() {
127			return ""
128		}
129		rows, err := duckDB.Query(`SELECT note FROM location_knowledge ORDER BY created_at DESC LIMIT 20`)
130		if err != nil {
131			return ""
132		}
133		defer rows.Close()
134	
135		var notes []string
136		for rows.Next() {
137			var note string
138			if rows.Scan(&note) == nil && note != "" {
139				if len(note) > 300 {
140					note = note[:300] + "…"
141				}
142				notes = append(notes, note)
143			}
144		}
145		if len(notes) == 0 {
146			return ""
147		}
148		var sb strings.Builder
149		sb.WriteString("LOCATION KNOWLEDGE BASE (curated context):\n")
150		for _, n := range notes {
151			sb.WriteString("- " + n + "\n")
152		}
153		return sb.String()
154	}
155	
156	// storeQAEmbeddingAsync saves a new Q&A + embedding in the background.
157	// embeddingChatID is the ID to use as chat_id (for later feedback linkage).
158	func storeQAEmbeddingAsync(ctx context.Context, embeddingChatID int64, question, answer string, embedding []float32) {
159		go func() {
160			if !duckDBAvailable() || len(embedding) == 0 {
161				return
162			}
163			embJSON, err := json.Marshal(embedding)
164			if err != nil {
165				return
166			}
167			id := time.Now().UnixNano()
168			if _, err := duckDB.Exec(
169				`INSERT INTO qa_embeddings (id, chat_id, question, answer, embedding, feedback_score) VALUES (?, ?, ?, ?, ?, 0)`,
170				id, embeddingChatID, question, answer, string(embJSON),
171			); err != nil {
172				log.Printf("store qa_embedding: %v", err)
173			}
174		}()
175	}
176	
177	// RecordFeedback updates the feedback score for a Q&A entry identified by chat_id.
178	// On positive feedback it also attempts to extract location knowledge from the answer.
179	func RecordFeedback(chatID int64, score int) error {
180		if !duckDBAvailable() {
181			return fmt.Errorf("analytics not available")
182		}
183		if score != 1 && score != -1 {
184			return fmt.Errorf("score must be +1 or -1")
185		}
186		// Always record in chat_feedback — this is what the admin page reads.
187		if _, err := duckDB.Exec(
188			`INSERT INTO chat_feedback (chat_id, score) VALUES (?, ?)`,
189			chatID, score,
190		); err != nil {
191			return fmt.Errorf("chat_feedback insert: %w", err)
192		}
193		// Best-effort update of semantic cache score (may have no matching row).
194		if _, err := duckDB.Exec(
195			`UPDATE qa_embeddings SET feedback_score = feedback_score + ? WHERE chat_id = ?`,
196			score, chatID,
197		); err != nil {
198			log.Printf("qa_embeddings feedback update (non-fatal): %v", err)
199		}
200		if score > 0 {
201			go extractLocationKnowledge(chatID)
202		}
203		return nil
204	}
205	
206	var coordRegexp = regexp.MustCompile(`(-?\d{1,3}\.\d{3,})[,\s]+(-?\d{1,3}\.\d{3,})`)
207	
208	// extractLocationKnowledge looks for lat/lon coordinates in the answer and
209	// stores a note in location_knowledge so future questions about that area
210	// automatically receive the context.
211	func extractLocationKnowledge(chatID int64) {
212		if !duckDBAvailable() {
213			return
214		}
215		var answer string
216		row := duckDB.QueryRow(`SELECT answer FROM qa_embeddings WHERE chat_id = ? LIMIT 1`, chatID)
217		if err := row.Scan(&answer); err != nil {
218			return
219		}
220		matches := coordRegexp.FindStringSubmatch(answer)
221		if len(matches) < 3 {
222			return
223		}
224		lat, err1 := strconv.ParseFloat(matches[1], 64)
225		lon, err2 := strconv.ParseFloat(matches[2], 64)
226		if err1 != nil || err2 != nil {
227			return
228		}
229		if math.Abs(lat) > 90 || math.Abs(lon) > 180 {
230			return
231		}
232		id := time.Now().UnixNano()
233		if _, err := duckDB.Exec(
234			`INSERT INTO location_knowledge (id, lat, lon, radius_m, note, source_chat_id) VALUES (?, ?, ?, 1000, ?, ?)`,
235			id, lat, lon, answer, chatID,
236		); err != nil {
237			log.Printf("location_knowledge insert: %v", err)
238		}
239	}
240	
241	// loadQAEmbeddings fetches Q&A rows from DuckLake.
242	// If positiveOnly is true, only rows with feedback_score > 0 are returned.
243	func loadQAEmbeddings(positiveOnly bool) ([]qaEntry, error) {
244		query := `SELECT id, question, answer, embedding, feedback_score FROM qa_embeddings`
245		if positiveOnly {
246			query += ` WHERE feedback_score > 0`
247		}
248		rows, err := duckDB.Query(query)
249		if err != nil {
250			return nil, err
251		}
252		defer rows.Close()
253	
254		var entries []qaEntry
255		for rows.Next() {
256			var e qaEntry
257			var embJSON string
258			if err := rows.Scan(&e.ID, &e.Question, &e.Answer, &embJSON, &e.FeedbackScore); err != nil {
259				continue
260			}
261			if err := json.Unmarshal([]byte(embJSON), &e.Embedding); err != nil {
262				continue
263			}
264			entries = append(entries, e)
265		}
266		return entries, rows.Err()
267	}
268	
269	// enrichSystemPrompt prepends RAG context and location knowledge to the base
270	// system prompt. Returns the original prompt unchanged if nothing is available.
271	func enrichSystemPrompt(base string, ragContext, locationKnowledge string) string {
272		var prefix strings.Builder
273		if ragContext != "" {
274			prefix.WriteString(ragContext)
275			prefix.WriteString("\n")
276		}
277		if locationKnowledge != "" {
278			prefix.WriteString(locationKnowledge)
279			prefix.WriteString("\n")
280		}
281		if prefix.Len() == 0 {
282			return base
283		}
284		return prefix.String() + base
285	}
