var match = window.location.pathname.match(/^\/trackid\/([a-zA-Z0-9]+)/);
if (match) {
  currentTrackID = match[1];
  isTrackView = true;
  sessionStorage.removeItem('dateRangeState'); // clear stale filter from previous session

  // Fetch bounds for single track
  fetch('/api/tracks/bounds?trackIDs=' + encodeURIComponent(currentTrackID))
    .then(function(response) { return response.json(); })
    .then(function(data) {
      if (data.status === 'success' && data.bounds) {
        trackBounds = [
          [data.bounds.minLat, data.bounds.minLon],
          [data.bounds.maxLat, data.bounds.maxLon]
        ];
        // If map is already initialized, fit bounds now
        if (map) {
          map.fitBounds(trackBounds);
        }
      }
    })
    .catch(function(err) {
      console.error('Error fetching track bounds:', err);
    });
}

// Initialize multiple tracks from path
var tracksMatch = window.location.pathname.match(/^\/tracks\/(.+)/);
if (tracksMatch) {
  var trackIDsParam = decodeURIComponent(tracksMatch[1]);
  currentTrackIDs = trackIDsParam.split(',').map(function(id) { return id.trim(); }).filter(function(id) { return id.length > 0; });
  if (currentTrackIDs.length > 0) {
    isTrackView = true;
    sessionStorage.removeItem('dateRangeState'); // clear stale filter from previous session

    // Fetch combined bounds for all tracks
    fetch('/api/tracks/bounds?trackIDs=' + encodeURIComponent(currentTrackIDs.join(',')))
      .then(function(response) { return response.json(); })
      .then(function(data) {
        if (data.status === 'success' && data.bounds) {
          trackBounds = [
            [data.bounds.minLat, data.bounds.minLon],
            [data.bounds.maxLat, data.bounds.maxLon]
          ];
          // If map is already initialized, fit bounds now
          if (map) {
            map.fitBounds(trackBounds);
          }
        }
      })
      .catch(function(err) {
        console.error('Error fetching track bounds:', err);
      });
  }
}

