  .ai-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 12px;
    white-space: nowrap;
  }

  .ai-table th,
  .ai-table td {
    border: 1px solid var(--modal-border);
    padding: 6px 10px;
    text-align: left;
  }

  .ai-table th {
    background-color: var(--control-bg);
    font-weight: 600;
    color: var(--modal-text);
  }

  .ai-table tr:nth-child(even) {
    background-color: var(--control-bg);
  }

  /* Feedback buttons */
  .ai-feedback-row {
    display: flex;
    gap: 6px;
    margin-top: 4px;
    padding: 0 2px;
    opacity: 0;
    transition: opacity .15s;
  }
  .ai-msg-row.bot:hover .ai-feedback-row { opacity: 1; }
  .ai-feedback-row.voted { opacity: 1; }
  .ai-feedback-btn {
    background: none;
    border: 1px solid rgba(255,255,255,0.15);
    border-radius: 6px;
    padding: 3px 7px;
    font-size: 12px;
    cursor: pointer;
    color: #c9a227;
    line-height: 0;
    transition: color .15s, border-color .15s;
  }
  .ai-feedback-btn:hover:not(:disabled) { color: #f9c74f; border-color: #f9c74f; }
  .ai-feedback-btn.active { color: #f9c74f; border-color: #f9c74f; }
  .ai-feedback-btn:disabled { cursor: default; opacity: 0.5; }
  .ai-cached-badge {
    font-size: 10px;
    color: var(--muted, #888);
    padding: 2px 5px;
    border: 1px solid rgba(255,255,255,0.15);
    border-radius: 6px;
    align-self: center;
  }
</style>

<button id="safecast-ai-toggle" aria-label="{{translate "ai_open"}}">
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"
    stroke-linecap="round" stroke-linejoin="round">
    <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path>
  </svg>
</button>

<div id="safecast-ai-panel">
  <div class="ai-panel-header">
    <div class="ai-panel-header-text">
      <h3>{{translate "ai_title"}}</h3>
      <span>{{translate "ai_subtitle"}}</span>
    </div>
    <div class="ai-header-actions">
      <button id="safecast-ai-expand" title="{{translate "ai_expand"}}" aria-label="{{translate "ai_expand"}}">
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"
          stroke-linecap="round" stroke-linejoin="round">
          <polyline points="15 3 21 3 21 9"></polyline>
          <polyline points="9 21 3 21 3 15"></polyline>
          <line x1="21" y1="3" x2="14" y2="10"></line>
          <line x1="3" y1="21" x2="10" y2="14"></line>
        </svg>
      </button>
      <button id="safecast-ai-close" title="{{translate "ai_close"}}" aria-label="{{translate "ai_close"}}">&times;</button>
    </div>
  </div>
  <div class="ai-panel-messages" id="ai-messages">
  </div>
  <div id="ai-panel-input-container">
    <form id="ai-form">
      <textarea id="ai-msg" rows="1" placeholder="{{translate "ai_placeholder"}}"></textarea>
      <button type="button" id="ai-search-map" title="{{translate "ai_search_map"}}" aria-label="{{translate "ai_search_map"}}">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"
          stroke-linecap="round" stroke-linejoin="round">
          <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"></path>
          <circle cx="12" cy="10" r="3"></circle>
        </svg>
      </button>
      <button type="submit" id="ai-send" title="{{translate "ai_send"}}">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"
          stroke-linecap="round" stroke-linejoin="round">
          <line x1="22" y1="2" x2="11" y2="13"></line>
          <polygon points="22 2 15 22 11 13 2 9 22 2"></polygon>
        </svg>
      </button>
    </form>
    <p id="ai-disclaimer">{{translate "ai_disclaimer"}}</p>
  </div>
</div>

<script>
  (function () {
    const toggleBtn = document.getElementById('safecast-ai-toggle');
    const closeBtn = document.getElementById('safecast-ai-close');
    const panel = document.getElementById('safecast-ai-panel');
    const form = document.getElementById('ai-form');
    const msgInput = document.getElementById('ai-msg');
    const messagesEl = document.getElementById('ai-messages');
    const sendBtn = document.getElementById('ai-send');

