  border-radius: 10px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-base);
  font-weight: bold;
  color: #fff;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
}

.ai-msg-row.user .ai-avatar {
  background: linear-gradient(135deg, #4caf50, #2e7d32);
}

.ai-msg-row.bot {
  position: relative;
}

.ai-msg-row.bot .ai-avatar {
  background: var(--control-bg);
  border: var(--modal-border);
}

.ai-bubble {
  word-break: break-word;
  font-size: var(--font-size-base);
  line-height: 1.6;
  opacity: 1;
  overflow-wrap: break-word;
}

.ai-msg-row.user .ai-bubble {
  background: #4caf50;
  padding: 12px 18px;
  border-radius: 20px 20px 4px 20px;
  color: #ffffff;
  max-width: 80%;
  box-shadow: 0 4px 15px rgba(76, 175, 80, 0.2);
}

.ai-timestamp {
  font-size: 11px;
  color: var(--text-muted, #999);
  margin-top: 2px;
  padding: 0 4px;
}

.ai-msg-row.user .ai-timestamp {
  text-align: right;
}

.ai-msg-row.bot .ai-bubble {
  padding: 0;
  background: transparent;
  border: none;
  max-width: 100%;
}

.ai-bubble a {
  color: var(--link-color);
  text-decoration: none;
}

.ai-bubble a:hover {
  text-decoration: underline;
}

.ai-bubble p {
  margin: 0 0 10px 0;
}

.ai-bubble p:last-child {
  margin: 0;
}

.ai-bubble ul,
.ai-bubble ol {
  margin: 10px 0;
  padding-left: 20px;
