async function saveTranslation() {
  const id = document.getElementById('editId').value;
  const lang = document.getElementById('editLang').value.trim();
  const key = document.getElementById('editKey').value.trim();
  const value = document.getElementById('editValue').value;

  if (!lang || !key) {
    alert('Language code and key are required');
    return;
  }

  try {
    let url, method, body;
    if (id) {
      // Update existing: PUT /api/admin/translations/{id}
      url = `/api/admin/translations/${id}`;
      if (PASSWORD) url += '?password=' + encodeURIComponent(PASSWORD);
      method = 'PUT';
      body = JSON.stringify({ value });
    } else {
      // Create new: POST /api/admin/translations
      url = '/api/admin/translations';
      if (PASSWORD) url += '?password=' + encodeURIComponent(PASSWORD);
      method = 'POST';
      body = JSON.stringify({ language_code: lang, key, value });
    }

    const resp = await fetch(url, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body
    });

    if (!resp.ok) {
      const text = await resp.text();
      throw new Error(text || 'HTTP ' + resp.status);
    }

    closeModal();
    fetchData();  // Reload table
  } catch (err) {
    alert('Save failed: ' + err.message);
  }
}
