				<button class="modal-save" onclick="saveEdit()">Save</button>
			</div>
		</div>
	</div>
	<div class="summary">
		<strong>Total Tracks:</strong> ` + strconv.Itoa(totalCount) + ` tracks
		<span style="margin-left: 20px;">
			<strong>Page ` + strconv.Itoa(page) + ` of ` + strconv.Itoa(totalPages) + `</strong>
