		if limit == 100 {
			return " selected"
		}
		return ""
	}() + `>100</option>
				<option value="250"` + func() string {
		if limit == 250 {
			return " selected"
		}
		return ""
	}() + `>250</option>
				<option value="500"` + func() string {
		if limit == 500 {
			return " selected"
		}
		return ""
	}() + `>500</option>
				<option value="1000"` + func() string {
		if limit == 1000 {
			return " selected"
		}
		return ""
	}() + `>1000</option>
			</select>
