48	// checkSemanticCache looks for a positively-rated cached answer with high
49	// cosine similarity to the given embedding. Returns ("", 0) on miss.
50	func checkSemanticCache(embedding []float32) (answer string, chatID int64) {
51		if !duckDBAvailable() || len(embedding) == 0 {
52			return "", 0
53		}
54		entries, err := loadQAEmbeddings(true)
55		if err != nil {
56			log.Printf("semantic cache load: %v", err)
57			return "", 0
58		}
59		var bestScore float32
60		var best *qaEntry
61		for i := range entries {
62			if s := cosineSimilarity(embedding, entries[i].Embedding); s > bestScore {
63				bestScore = s
64				best = &entries[i]
